import Dexie from 'dexie';

// Define the database with enhanced offline support
export class AwardDatabase extends Dexie {
  constructor() {
    super('AwardManagementDB');
    
    this.version(1).stores({
      initiatives: '++id, name, department, status, completion_percentage, planned_budget, used_budget, responsible_person, priority, start_date, end_date, description, created_at, updated_at, sync_status, last_modified',
      awardPoints: '++id, point_type, standard, standard_classification, department, description, status, responsible_person, created_at, updated_at, sync_status, last_modified',
      departments: '++id, name, active, sync_status, last_modified',
      settings: '++id, key, value, sync_status, last_modified',
      syncQueue: '++id, table_name, record_id, operation, data, timestamp, retries, max_retries, error_message',
      offlineActions: '++id, action_type, data, timestamp, processed'
    });

    // Add hooks for automatic sync tracking
    this.initiatives.hook('creating', this.addSyncMetadata);
    this.initiatives.hook('updating', this.updateSyncMetadata);
    this.awardPoints.hook('creating', this.addSyncMetadata);
    this.awardPoints.hook('updating', this.updateSyncMetadata);
    this.departments.hook('creating', this.addSyncMetadata);
    this.departments.hook('updating', this.updateSyncMetadata);
  }

  // Add sync metadata to new records
  addSyncMetadata = (primKey, obj, trans) => {
    obj.sync_status = 'pending';
    obj.last_modified = new Date();
  };

  // Update sync metadata on record updates
  updateSyncMetadata = (modifications, primKey, obj, trans) => {
    modifications.sync_status = 'pending';
    modifications.last_modified = new Date();
  };
}

