// Helper functions for data operations
export const getInitiatives = () => db.initiatives.orderBy('updated_at').reverse().toArray();
export const getAwardPoints = () => db.awardPoints.orderBy('updated_at').reverse().toArray();
export const getDepartments = () => db.departments.where('active').equals(1).toArray();

export const addInitiative = async (initiative) => {
  const now = new Date();
  return await db.initiatives.add({
    ...initiative,
    created_at: now,
    updated_at: now
  });
};

export const updateInitiative = async (id, updates) => {
  return await db.initiatives.update(id, {
    ...updates,
    updated_at: new Date()
  });
};

export const deleteInitiative = async (id) => {
  return await db.initiatives.delete(id);
};

