// Get records that need syncing
export const getRecordsNeedingSync = async () => {
  const [initiatives, awardPoints, departments] = await Promise.all([
    db.initiatives.where('sync_status').anyOf(['pending', 'pending_delete']).toArray(),
    db.awardPoints.where('sync_status').anyOf(['pending', 'pending_delete']).toArray(),
    db.departments.where('sync_status').anyOf(['pending', 'pending_delete']).toArray()
  ]);
  
  return {
    initiatives,
    awardPoints,
    departments,
    total: initiatives.length + awardPoints.length + departments.length
  };
};

// Mark record as synced
export const markRecordSynced = async (tableName, recordId) => {
  const table = db[tableName];
  if (table) {
    await table.update(recordId, {
      sync_status: 'synced',
      last_modified: new Date()
    });
  }
};

// Get sync statistics
export const getSyncStatistics = async () => {
  const [pendingOperations, unprocessedActions, recordsNeedingSync] = await Promise.all([
    getPendingSyncOperations(),
    getUnprocessedOfflineActions(),
    getRecordsNeedingSync()
  ]);
  
  return {
    pendingOperations: pendingOperations.length,
    unprocessedActions: unprocessedActions.length,
    recordsNeedingSync: recordsNeedingSync.total,
    lastSyncAttempt: await getSetting('last_sync_attempt'),
    lastSuccessfulSync: await getSetting('last_successful_sync')
  };
};

// Update sync timestamps
export const updateSyncTimestamp = async (type, timestamp = new Date()) => {
  await setSetting(type, timestamp.toISOString());
};

// Clear sync queue (for testing/debugging)
export const clearSyncQueue = async () => {
  await db.syncQueue.clear();
  await db.offlineActions.clear();
  console.log('Sync queue and offline actions cleared');
};

// Export data for backup/sync
export const exportDataForSync = async () => {
  const [initiatives, awardPoints, departments, settings] = await Promise.all([
    db.initiatives.toArray(),
    db.awardPoints.toArray(),
    db.departments.toArray(),
    db.settings.toArray()
  ]);
  
  return {
    initiatives,
    awardPoints,
    departments,
    settings,
    exportTimestamp: new Date().toISOString()
  };
};

// Import data from sync
export const importDataFromSync = async (data) => {
  try {
    await db.transaction('rw', [db.initiatives, db.awardPoints, db.departments, db.settings], async () => {
      // Clear existing data
      await db.initiatives.clear();
      await db.awardPoints.clear();
      await db.departments.clear();
      await db.settings.clear();
      
      // Import new data
      if (data.initiatives?.length) await db.initiatives.bulkAdd(data.initiatives);
      if (data.awardPoints?.length) await db.awardPoints.bulkAdd(data.awardPoints);
      if (data.departments?.length) await db.departments.bulkAdd(data.departments);
      if (data.settings?.length) await db.settings.bulkAdd(data.settings);
    });
    
    console.log('Data imported successfully from sync');
    return { success: true };
  } catch (error) {
    console.error('Failed to import data from sync:', error);
    return { success: false, error: error.message };
  }
};
